            "knowledge_value": "high",
            "reason": "该段落包含大量可沉淀的知识候选片段，如公司基本信息、业务结构、财务数据、运营模式等，这些内容具有稳定性和可复用性。同时，段落中也包含一些事件性描述（如具体年份的财务表现、海外扩张等），因此采用split决策，优先提取知识部分，剩余事件部分作为event_residue。",
            "knowledge_spans": [
                {
                    "text": "泡泡玛特（POP MART）成立于2010年，总部位于北京，是中国领先的潮流文化娱乐公司，以“创造潮流，传递美好”为核心理念。公司于2020年在港交所上市（股票代码：09992.HK），2024年市值已超2591亿港元，成为全球潮玩行业龙头企业。截至2024年，其业务覆盖IP孵化、潮玩零售、主题乐园、数字娱乐四大领域，构建了完整的潮玩产业链。",
                    "role": "公司基本信息与业务结构",
                    "stability": "high"
                },
                {
                    "text": "拥有MOLLY、SKULLPANDA、DIMOO等10个年销售额过亿的头部IP，并通过与全球350+设计师合作持续孵化新IP。",
                    "role": "IP矩阵与孵化模式",
                    "stability": "medium"
                },
                {
                    "text": "以盲盒为主（单价59-99元），延伸至手办、拼装积木、联名商品等，并通过主题乐园（如北京泡泡玛特城市乐园）增强体验。",
                    "role": "产品形态与体验拓展",
                    "stability": "medium"
                },
                {
                    "text": "截至2024年，海外门店超92家，覆盖80多个国家，海外收入占比30%，毛利率达70.1%。",
                    "role": "全球化布局与财务指标",
                    "stability": "medium"
                },
                {
                    "text": "2024年营收131.22亿元，同比增长102%；净利润33.08亿元，毛利率长期维持在60%-70%。",
                    "role": "财务数据表现",
                    "stability": "low"
                },
                {
                    "text": "中国内地注册会员超3400万，复购率43.9%。",
                    "role": "用户规模与复购率",
                    "stability": "medium"
                },
                {
                    "text": "自有IP贡献主要收入（如MOLLY曾占30%），并通过分成模式绑定设计师，降低版权依赖。",
                    "role": "IP驱动收入模式",
                    "stability": "high"
                },
                {
                    "text": "从盲盒拓展至动画、游戏、主题乐园，延长IP生命周期。",
                    "role": "全场景渗透策略",
                    "stability": "high"
                },
                {
                    "text": "盲盒毛利率达60%-70%，2024年上半年IP授权收入7亿元，占比15.2%。",
                    "role": "盲盒盈利与授权收入",
                    "stability": "medium"
                },
                {
                    "text": "全球500+门店（含机器人商店），覆盖一二线城市商圈。",
                    "role": "线下销售网络布局",
                    "stability": "medium"
                },
                {
                    "text": "天猫、抖音等平台占线上销售60%，微信抽盒机结合社交裂变提升粘性。",
                    "role": "线上销售渠道与社交互动",
                    "stability": "medium"
                },
                {
                    "text": "付费会员（如“优享卡”）贡献超90%收入，提供优先购、积分兑换等权益。",
                    "role": "会员体系与收入贡献",
                    "stability": "high"
                },
                {
                    "text": "隐藏款在闲鱼等平台溢价数十倍，反哺品牌热度。",
                    "role": "二手市场溢价效应",
                    "stability": "medium"
                },
                {
                    "text": "与华为、迪士尼等品牌合作推出联名产品，拓展消费场景。",
                    "role": "跨界联名合作",
                    "stability": "medium"
                }
            ],
            "event_residue": "2023年SKULLPANDA和MOLLY分别贡献收入10.24亿和10.2亿元。2024年海外门店扩张至西班牙、法国等地。2024年海外营收同比增259%，欧洲市场直营门店单店月均销售额超百万欧元。",
            "drop_target": "event"
        }
    ]
}
